import sys

data = sys.stdin.read().split()
r, c = int(data[0]), int(data[1])
g = data[2:2 + r]
INF = 10 ** 9
dist = {}
for i in range(r):
    for j in range(c):
        for u in range(3):
            dist[(i, j, u)] = INF
dist[(0, 0, 0)] = 0
changed = True
while changed:
    changed = False
    for (i, j, u), d in list(dist.items()):
        if d >= INF:
            continue
        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            # run of m blocked cells followed by an open landing cell (m = 0 is an ordinary step)
            for m in range(0, 3):
                if u + m > 2:
                    break
                ok = True
                for t in range(1, m + 1):
                    a, b = i + di * t, j + dj * t
                    if not (0 <= a < r and 0 <= b < c) or g[a][b] != '1':
                        ok = False
                a, b = i + di * (m + 1), j + dj * (m + 1)
                if not ok or not (0 <= a < r and 0 <= b < c) or g[a][b] != '0':
                    continue
                if d + 1 < dist[(a, b, u + m)]:
                    dist[(a, b, u + m)] = d + 1
                    changed = True
best = min(dist[(r - 1, c - 1, u)] for u in range(3))
print(best if best < INF else -1)

